import{_ as i,c as n,o as r,ae as t}from"./chunks/framework.Bw0Gm4PQ.js";const f=JSON.parse('{"title":"TRANSPARENCY REGARDING FOREIGN INFLUENCE","description":"","frontmatter":{"title":"TRANSPARENCY REGARDING FOREIGN INFLUENCE","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/transparency-regarding-foreign-influence-at-american-universities/","publishDate":"2025-04-23T18:16:48-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-23-transparency-regarding-foreign-influence.md","filePath":"executive-orders/2025-04-23-transparency-regarding-foreign-influence.md"}'),o={name:"executive-orders/2025-04-23-transparency-regarding-foreign-influence.md"};function a(s,e,l,c,u,d){return r(),n("div",null,e[0]||(e[0]=[t('<h1 id="transparency-regarding-foreign-influence" tabindex="-1">TRANSPARENCY REGARDING FOREIGN INFLUENCE <a class="header-anchor" href="#transparency-regarding-foreign-influence" aria-label="Permalink to &quot;TRANSPARENCY REGARDING FOREIGN INFLUENCE&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/transparency-regarding-foreign-influence-at-american-universities/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/transparency-regarding-foreign-influence-at-american-universities/</a></p><p>Published: 2025-04-23T18:16:48-04:00</p><ul><li><p><strong>Authority</strong>: The Executive Order is issued under the President&#39;s authority as granted by the Constitution and U.S. laws.</p></li><li><p><strong>Higher Education Act of 1965</strong>: Section 117 requires higher education institutions to report significant foreign funding but has not been adequately enforced.</p></li><li><p><strong>Lack of Transparency</strong>: Many universities failed to disclose over half of the reportable foreign gifts from 2010 to 2016, resulting in unknown amounts and sources of foreign funding.</p></li><li><p><strong>Protection of Interests</strong>: The Administration emphasizes the need for transparency regarding foreign funding to protect American educational, cultural, and national security interests.</p></li><li><p><strong>Past Investigations</strong>: The Department of Education previously investigated 19 campuses (2019-2021), uncovering $6.5 billion in previously undisclosed foreign funds, but such efforts were rolled back by the prior administration.</p></li><li><p><strong>Policy Goals</strong>:</p><ul><li>End secrecy surrounding foreign funds in educational institutions.</li><li>Protect the marketplace of ideas from foreign propaganda.</li><li>Safeguard students and research from foreign exploitation.</li></ul></li><li><p><strong>Actions for Enforcement</strong>:</p><ul><li>The Secretary of Education is directed to enforce section 1011f, working with the Attorney General and other entities.</li><li>Actions include: <ul><li>Rescinding prior exemptions that allowed secrecy in foreign funding.</li><li>Requiring detailed disclosures of foreign funding sources and purposes.</li><li>Improving public access to foreign funding information.</li><li>Holding noncompliant institutions accountable through audits and investigations.</li></ul></li></ul></li><li><p><strong>Compliance with Federal Funds</strong>: Higher education institutions must comply with foreign funding disclosure requirements to receive federal grant funds. Noncompliance will result in ineligibility for such funds.</p></li><li><p><strong>Legal Provisions</strong>:</p><ul><li>The order does not impact existing legal authority of executive departments or agencies.</li><li>Implementation to align with applicable laws and funding availability.</li><li>The order does not create enforceable rights for individuals against the U.S. or its entities.</li><li>If any part of the order is deemed invalid, other provisions remain unaffected.</li></ul></li></ul>',4)]))}const p=i(o,[["render",a]]);export{f as __pageData,p as default};
